from datetime import datetime
import re


_UNIT = re.compile(r"[A-Za-z0-9][A-Za-z0-9@_.-]*\.service\Z")


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
