from __future__ import annotations


def ssh_authentication_violations(config: dict[str, object]) -> tuple[str, ...]:
    violations: list[str] = []
    if config.get("pubkey_authentication") is not True:
        violations.append("public_key_authentication_must_be_enabled")
    if config.get("password_authentication") is not False:
        violations.append("password_authentication_must_be_disabled")
    if config.get("kbd_interactive_authentication") is not False:
        violations.append("keyboard_interactive_authentication_must_be_disabled")
    if config.get("permit_root_login") != "no":
        violations.append("direct_root_login_must_be_disabled")
    methods = config.get("authentication_methods")
    if not isinstance(methods, str) or not methods.strip():
        violations.append("authentication_methods_is_required")
    else:
        alternatives = [item.strip().split(",") for item in methods.split()]
        if any(not alternative or any(method != "publickey" for method in alternative) for alternative in alternatives):
            violations.append("authentication_methods_must_use_public_key_only")
    return tuple(violations)


def ssh_authentication_is_hardened(config: dict[str, object]) -> bool:
    return not ssh_authentication_violations(config)

import unittest

from scripts.validate_ssh_authentication_methods import ssh_authentication_is_hardened, ssh_authentication_violations


class SSHAuthenticationMethodContractTests(unittest.TestCase):
    def test_public_key_only_configuration_passes(self):
        config = {"pubkey_authentication": True, "password_authentication": False, "kbd_interactive_authentication": False, "permit_root_login": "no", "authentication_methods": "publickey"}
        self.assertTrue(ssh_authentication_is_hardened(config))

    def test_password_keyboard_interactive_and_root_login_fail(self):
        config = {"pubkey_authentication": True, "password_authentication": True, "kbd_interactive_authentication": True, "permit_root_login": "prohibit-password", "authentication_methods": "publickey,password"}
        violations = ssh_authentication_violations(config)
        self.assertIn("password_authentication_must_be_disabled", violations)
        self.assertIn("keyboard_interactive_authentication_must_be_disabled", violations)
        self.assertIn("direct_root_login_must_be_disabled", violations)
        self.assertIn("authentication_methods_must_use_public_key_only", violations)
